-- ===================================================================== 011_evidence.sql
-- SPDX-License-Identifier: GPL-3.0-only
-- 011_evidence: the evidence item behind a fredpd_evidence row, recorded when fredpd_forensics first sees it
-- (docs/modules/forensics.md "Uid registry", docs/deps-verification.md Decision 5.2). evidences lets a client rewrite
-- item metadata (item_uid included) until its security patch is applied, so every later collect / hand-in / analysis
-- event for the uid is compared with these two columns and refused (audited evidence.mismatch) when they differ.
--   item_name  ox_inventory item name (collected_fingerprint, collected_casing ...), set when the row is created
--   ident      evidence identity, set once: 'fingerprint:<string>', 'dna:<string>' or
--              'ballistics:<owner>|<serial>|<weapon type>|<kind>' (NULL until the item carries evidence)
-- Both stay NULL on rows created before this migration and are filled at the next sighting of the item.

ALTER TABLE fredpd_evidence
  ADD COLUMN IF NOT EXISTS item_name VARCHAR(64) NULL COMMENT 'ox_inventory item name first seen for item_uid' AFTER item_uid,
  ADD COLUMN IF NOT EXISTS ident VARCHAR(191) NULL COMMENT 'evidence identity first seen for item_uid' AFTER item_name;

INSERT INTO fredpd_migrations (id, checksum) VALUES ('011_evidence.sql', '73035d6b7bc04c9b6b77468cbf12618db92c9b64eb9708e785fee5ecc87c6ac6') ON DUPLICATE KEY UPDATE id = id;

-- ===================================================================== 013_records.sql
-- SPDX-License-Identifier: GPL-3.0-only
-- 013_records: additive columns for the Phase 5 writes of fredpd_records (docs/modules/records.md).
--   fredpd_cases.resolution          the closing note of closeCase (the level stays after close, §C14)
--   fredpd_shares.max_level          highest level a share link may show: the creator's tier when it was created, so a
--                                    link never shows more than its creator could read by tier (assignment-only
--                                    access does not travel with a link)
--   fredpd_release_requests.channel  where the request came in: 'station' (ox_target) or 'portal'
-- No ENUMs here (enum values need locale keys, packages/types/test/locales.test.ts). Obehörig sökning needs no table:
-- it counts fredpd_audit rows through idx (actor_citizenid, created_at) on each person lookup.

ALTER TABLE fredpd_cases
  ADD COLUMN IF NOT EXISTS resolution TEXT NULL COMMENT 'closing note (closeCase)' AFTER summary;

ALTER TABLE fredpd_shares
  ADD COLUMN IF NOT EXISTS max_level TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'highest level the link shows' AFTER target_id;

ALTER TABLE fredpd_release_requests
  ADD COLUMN IF NOT EXISTS channel VARCHAR(16) NULL COMMENT 'station | portal' AFTER requester_name;

INSERT INTO fredpd_migrations (id, checksum) VALUES ('013_records.sql', 'e7a55e8fe66ee416ee20a6a88c5897adf7a3564ed192a3432a4360f3698c6ab7') ON DUPLICATE KEY UPDATE id = id;

-- ===================================================================== seed/charges_sv.sql
-- SPDX-License-Identifier: GPL-3.0-only
-- Brottskatalog (fredpd_charges, 003_records.sql): Swedish charges for the game. Sweden has no licence points;
-- traffic consequences beyond the fine (varning / återkallelse) are handled in reports, not here.
--
-- fine is in SEK and game-balanced (not the real amounts); jail_min is game jail time in minutes; class is
-- 'ordningsbot' (on-the-spot fine), 'bot' (böter via strafföreläggande / domstol) or 'fängelse'.
-- law_ref: BrB = brottsbalken, TBL = lag (1951:649) om straff för vissa trafikbrott, TrF = trafikförordningen
